fn read_uniforms() -> Uniforms {
    unsafe {
        let o = UNIFORMS_OFFSET;
        Uniforms {
            w: maxf(read_i32(o) as f32, 1.0),
            h: maxf(read_i32(o + 4) as f32, 1.0),
